static Frame read(FrameStore& s){std::optional<Frame> f;assert(s.copy_confirmed(f)==FrameStatus::ok&&f);return *f;}
static void binary(const std::string& name,const Frame& f){std::ofstream s(output+"/"+name+".bgra",std::ios::binary);assert(s);s.write(reinterpret_cast<const char*>(f.pixels.data()),f.pixels.size());s.close();assert(s);}
static void seed(FrameStore& s,int w,int h){assert(s.resize({w,h,1})==FrameStatus::ok);FrameStore::Token t;assert(s.prepare(t)==FrameStatus::ok);std::span<std::uint8_t> b;assert(s.candidate(t,b)==FrameStatus::ok);for(std::size_t i=0;i<b.size();i+=4){b[i]=(i/4)%127;b[i+1]=17;b[i+2]=53;b[i+3]=255;}assert(s.commit(t)==FrameStatus::ok);}
static void same(const Frame& a,const Frame& b){assert(a.sequence==b.sequence&&a.viewport.width==b.viewport.width&&a.viewport.height==b.viewport.height&&a.viewport.dpi==b.viewport.dpi&&a.stride==b.stride&&a.pixels==b.pixels);}
static p::PreparedFrame prep(const std::vector<p::Command>& c){auto r=p::prepare({c,true});assert(std::holds_alternative<p::PreparedFrame>(r));return std::get<p::PreparedFrame>(std::move(r));}
static void reject_prepare(const std::string& name,std::vector<p::Command> c,p::ErrorCode expected){FrameStore store;seed(store,16,12);auto before=read(store);auto r=p::prepare({std::move(c),true});auto* error=std::get_if<p::Error>(&r);auto after=read(store);binary(name+"-before",before);binary(name+"-after",after);std::printf("PREP %s expected=%d actual=%d sequence=%llu/%llu\n",name.c_str(),int(expected),error?int(error->code):-1,(unsigned long long)before.sequence,(unsigned long long)after.sequence);std::fflush(stdout);assert(error&&error->code==expected);same(before,after);++prep_failures;}
